package net.officefloor.hq.app.claim;

/** A validated proof added to a claim: who is adding it. */
public record ProofInput(String user) {
}
package net.officefloor.hq.app.claim;

/** Body of adding a proof to a claim: who is adding it. */
public record ProofRequest(String user) {
}
package net.officefloor.hq.app.claim;

import java.util.List;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Raise the loaded claim's proofs count by one: not on a SETTLED or VOID claim. A proof another user's change got
 *  to first is refused. */
public class SaveProof {
    public void save(@Val ProofInput input, @Val Claim loaded, SheetRepository sheets, ClaimRepository repository,
            Out<ClaimResponse> saved) throws ClaimStatusNotAllowedException {
        if (loaded.status() == ClaimStatus.SETTLED || loaded.status() == ClaimStatus.VOID) {
            throw new ClaimStatusNotAllowedException("A " + loaded.status() + " claim cannot be given a proof.");
        }
        if (!repository.addProof(loaded)) {
            throw new ClaimStatusNotAllowedException("The claim changed meanwhile; load the sheet again.");
        }
        saved.set(ClaimResponse.from(new Claim(loaded.id(), loaded.sheetId(), loaded.personId(), loaded.amount(),
                loaded.date(), loaded.note(), loaded.status(), loaded.number(), loaded.settledDue(),
                loaded.openedBy(), loaded.stated(), loaded.statedDue(), loaded.corrects(), loaded.dueBy(),
                loaded.deferredUntil(), loaded.proofs() + 1, loaded.splitFrom(), loaded.lateEntry(), loaded.reminded(), loaded.ref(), loaded.tags(), loaded.waived()), List.of(), sheets.today(loaded.sheetId())));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;

/** Record the stored proof in the audit file, naming the claim like every claim line, then its proofs count now. */
public class AuditClaimProofAdded {
    public void audit(@Val ProofInput input, @Val Claim loaded, @Val ClaimResponse saved, PersonRepository people,
            Audit audit) {
        var person = people.find(loaded.sheetId(), loaded.personId());
        audit.record("CLAIM_PROOF_ADDED sheet=" + loaded.sheetId() + " by=" + input.user()
                + " person=" + person.name() + " amount=" + saved.amount() + " date=" + saved.date()
                + (saved.number() != null ? " number=" + saved.number() : "")
                + " proofs=" + saved.proofs());
    }
}
-- A claim's proofs count, raised by one at a time (never on a SETTLED or VOID claim). A claim whose due is above the
-- sheet's proof threshold in force on its date cannot be settled or approved while it has none. The proof threshold
-- is a dated setting (setting_value key proof-threshold; blank: none).
