content.content:
 *  grade's in force on that date, else the sheet's), past Saturdays, Sundays and the sheet's holidays now, and its
 *  status log: one line per status it has had, oldest first, as <STATUS> by <user> on <date> due=<due>, and the date
 *  it is deferred until (yyyy-mm-dd; null when never deferred) and whether it is deferred on the sheet's today (an
 *  OPEN claim deferred until after it: it counts in no total, is not overdue and cannot be settled), and its proofs
 *  count (raised one at a time, not on a SETTLED or VOID claim; one whose due is above the proof threshold in force
 *  on its date cannot be settled or approved while it is 0 — the server refuses it), and the number
 *  of the claim it was split from (null when it was not split off one), and the last sheet-today it was reminded
 *  (yyyy-mm-dd; null when never: only an OPEN or PENDING claim, once per sheet-today), and its external reference
 *  (null when none: unique on the sheet without regard to case — the server refuses a repeat), and its tags (trimmed,
 *  lower-cased, without repeats, sorted; empty when none), and its comments, oldest first, as <user> on <date>: <text>
 *  (the date being the sheet's today when it was written), and the number of the settle batch that settled it (null when
 *  none did: it was settled one at a time, or is not settled), and its lines, in the order added, as
 *  <label> <qty> x <unit> (only a DRAFT takes a line; a claim with lines has their total as its amount — the server
 *  refuses an edit typing another), and its review day (yyyy-mm-dd): the sheet's today when it went to REVIEW (null
 *  when it never did), and whether a steward waived its late charge (only an OPEN or PENDING claim, once: it then
 *  bears no late charge, overdue or not). */
export type Claim = { id: number; personId: number; amount: string; date: string; note: string; status: ClaimStatus;
  number: string | null; settledDue: string | null; openedBy: string | null; stated: boolean;
  statedDue: string | null; corrects: string | null; dueBy: string; log: string[];
  deferredUntil: string | null; deferred: boolean; proofs: number; splitFrom: string | null;
  lateEntry: boolean; reminded: string | null; ref: string | null; tags: string[];
  comments: string[]; batch: number | null; lines: string[]; reviewOn?: string | null;
  waived: boolean };

/** Whether a claim counts toward claimed, due-total and every total: only OPEN, PENDING and SETTLED ones do, except
 *  one deferred on the sheet's today. */
      putJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${claim.id}/reassign`, { user, personId }),
    onSuccess: async () => {
      setMoveTo('');
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
    onError: (e) =>
      setError(e instanceof HttpError && (e.status === 409 || e.status === 400 || e.status === 404) && e.body
        ? e.body : `Could not move this ${claim.status} claim.`),
  });

  const proof = useMutation({
    mutationFn: () =>
      postJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${claim.id}/proof`, { user }),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
    onError: (e) =>
      setError(e instanceof HttpError && (e.status === 409 || e.status === 400 || e.status === 404) && e.body
        ? e.body : `Could not add a proof to this ${claim.status} claim.`),
  });

  const defer = useMutation({
    mutationFn: (until: string) =>
      putJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${claim.id}/defer`, { user, until }),
    onSuccess: async () => {
      setDeferUntil('');
      Due by <span data-testid="claim-due-by">{dueBy(claim)}</span>{' '}
      Overdue <span data-testid="claim-overdue">{overdue(claim, today, late.grace(claim)) ? 'yes' : 'no'}</span>{' '}
      Review late <span data-testid="claim-review-late">{reviewLate(claim, today, reviewSla) ? 'yes' : 'no'}</span>{' '}
      Period <span data-testid="claim-period">{period?.name ?? ''}</span>{' '}
      Late entry <span data-testid="claim-late-entry">{claim.lateEntry ? 'yes' : 'no'}</span>{' '}
      Stated <span data-testid="claim-stated">{claim.stated ? 'yes' : 'no'}</span>{' '}
      Deferred <span data-testid="claim-deferred">{claim.deferred ? 'yes' : 'no'}</span>{' '}
      until <span data-testid="claim-deferred-until">{claim.deferredUntil ?? ''}</span>{' '}
      Proofs <span data-testid="claim-proofs">{claim.proofs}</span>{' '}
      Split from <span data-testid="claim-split-from">{claim.splitFrom ?? ''}</span>{' '}
      Reminded <span data-testid="claim-reminded">{claim.reminded ?? ''}</span>{' '}
      Waived <span data-testid="claim-waived">{claim.waived ? 'yes' : 'no'}</span>{' '}
      Batch <span data-testid="claim-batch">{claim.batch ?? ''}</span>{' '}
      <ol data-testid="claim-log">
        {claim.log.map((line, i) => (
          <li key={i} data-testid="claim-log-line">{line}</li>
        data-testid="claim-reassign"
        disabled={reassign.isPending}
        onClick={() => {
          clearError();
          if (moveTo === '') {
            setError('Choose the person to move this claim to.');
            return;
          }
          reassign.mutate(moveTo);
        }}
      >
        Move
      </button>{' '}
      <button
        type="button"
        data-testid="claim-proof"
        disabled={proof.isPending}
        onClick={() => {
          clearError();
          proof.mutate();
        }}
      >
        Add proof
      </button>{' '}
      <input
        data-testid="claim-defer-date"
        placeholder="Defer until yyyy-mm-dd"
        value={deferUntil}
        onChange={(e) => {
          clearError();
          setDeferUntil(e.target.value);
 *  is the alert threshold with two decimals (not dated; '' when off): a person whose due-total crosses above it over a
 *  change is alerted in the audit file. `rounding` is the rounding mode in force (half-up or half-even; '' when none),
 *  dated (key rounding): a claim whose date has one in force rounds its live figures by it, else by the policy date. `reviewThreshold` is the review threshold with two decimals in force ('' when none), dated (key
 *  review-threshold): a claim whose due is above the one in force on its date goes to REVIEW when opened. `escalateAfter` is the escalation gap in days (not dated; '' when off): reminding a
 *  claim whose previous reminder was at least that many days before the sheet's today escalates it, once ever.
 *  `reviewSla` is the review SLA in days (not dated; '' when none): a REVIEW claim whose review day plus it is before
 *  the sheet's today is review-late (see reviewLate). */
export type Settings = { clerkLimit: string; floor: string; terms: string; latePct: string; policyDate: string;
  periodNumberingFrom: string; gradeTerms: Record<string, string>; cap: string; proofThreshold?: string; noteThreshold?: string; dated?: Record<string, Dated[]>;
  perms?: Record<string, string>; graceDays?: string; entryDate?: string; gradeGrace?: Record<string, string>;
  gradeProofThreshold?: Record<string, string>; pot?: string; parent?: string; fiscalStartMonth?: string; alertThreshold?: string;
  rounding?: string; reviewThreshold?: string; escalateAfter?: string; reviewSla?: string };

/** A dated setting's value ('' when blank) in force from its from-date (yyyy-mm-dd). */
export type Dated = { from: string; value: string };

